window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ffa2fbd3856cdca6"]={"versions": [{"id": "FIG-ffa2fbd3856cdca6", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (State Machine) aus der Spezifikation des Diagnostic Event Manager (Dem) in der AUTOSAR Classic Platform. Das Diagramm modelliert die Zustandslogik des DTC-Statusbits 0 (<code>TestFailed</code>) gemäß ISO 14229-1 (UDS) auf Basis von Dem-internen Ereignisstatusmeldungen und Diagnose-Serviceaufrufen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Zustände:</strong></li>\n<li><code>Initial state</code> (Startpseudozustand)</li>\n<li><code>TestFailed = FALSE</code> (Bit 0 nicht gesetzt)</li>\n<li><code>TestFailed = TRUE</code> (Bit 0 gesetzt)</li>\n<li><strong>Schnittstellen & Operationen:</strong></li>\n<li><code>Dem_SetEventStatus(EventId, EventStatus)</code> / <code>Dem_ReportErrorStatus(EventId, EventStatus)</code> mit den Statuswerten <code>DEM_EVENT_STATUS_PASSED</code> und <code>DEM_EVENT_STATUS_FAILED</code></li>\n<li><code>Dem_ResetEventStatus(EventId)</code> (gemäß <code>[SWS_Dem_00187]</code>)</li>\n<li><code>Dem_&lt;…&gt;ClearDTC(DTC, DTCFormat, DTCOrigin)</code> (gemäß <code>[SWS_Dem_00385]</code>)</li>\n<li><strong>Signal/Status:</strong></li>\n<li>Statusbit 0 (<code>Bit 0</code> bzw. <code>TestFailed</code>) des DTC-Status-Bytes.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung:</strong> Beim Eintritt über den Startzustand (<code>Initial state</code>) wird Bit 0 auf den Initialwert gesetzt; der Folgezustand ist <code>TestFailed = FALSE</code>.</li>\n<li><strong>Übergang nach TRUE:</strong> Aus dem Zustand <code>TestFailed = FALSE</code> führt das Ereignis <code>Dem_[SetEvent|ReportError]Status(EventId, EventStatus = DEM_EVENT_STATUS_FAILED)</code> [B] in den Zustand <code>TestFailed = TRUE</code>.</li>\n<li><strong>Selbstübergang TRUE:</strong> Tritt im Zustand <code>TestFailed = TRUE</code> erneut <code>Dem_[SetEvent|ReportError]Status(EventId, EventStatus = DEM_EVENT_STATUS_FAILED)</code> auf, verbleibt das Bit im Zustand <code>TestFailed = TRUE</code>.</li>\n<li><strong>Rückfall nach FALSE:</strong> Ein Zustandswechsel von <code>TestFailed = TRUE</code> nach <code>TestFailed = FALSE</code> erfolgt durch logisches ODER dreier Auslöser [A]:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Dem_[SetEvent|ReportError]Status(EventId, EventStatus = DEM_EVENT_STATUS_PASSED)</code></li>\n<li><code>Dem_ResetEventStatus(EventId)</code></li>\n<li><code>Dem_&lt;…&gt;ClearDTC(DTC, DTCFormat, DTCOrigin)</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Selbstübergang FALSE:</strong> Im Zustand <code>TestFailed = FALSE</code> belässt der Aufruf von <code>Dem_[SetEvent|ReportError]Status(EventId, EventStatus = DEM_EVENT_STATUS_PASSED)</code> das Bit unverändert auf <code>FALSE</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Das Verhalten ist für AUTOSAR Dem-Implementierungen normativ verbindlich für die Verwaltung des Bit 0 im UDS DTCStatusByte.</li>\n<li>Implementierer müssen beachten, dass nicht nur ein explizites Testergebnis (<code>DEM_EVENT_STATUS_PASSED</code>), sondern auch das Zurücksetzen (<code>Dem_ResetEventStatus</code>) oder das Löschen von DTCs (<code>Dem_&lt;…&gt;ClearDTC</code>) das Bit 0 auf 0 (<code>FALSE</code>) zurücksetzt.</li>\n<li>Diagnose-Fehlerberichte (<code>DEM_EVENT_STATUS_FAILED</code>) setzen das Bit unmittelbar auf 1 (<code>TRUE</code>), unabhängig davon, ob zuvor ein Pass vorlag.</li>\n</ul>"}, {"id": "FIG-d40571ea7894622b", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (State Machine) aus der Spezifikation des Diagnostic Event Manager (Dem) in der AUTOSAR Classic Platform. Das Diagramm modelliert die Zustandslogik des DTC-Statusbits 0 (<code>TestFailed</code>) gemäß ISO 14229-1 (UDS) auf Basis von Dem-internen Ereignisstatusmeldungen und Diagnose-Serviceaufrufen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Zustände:</strong></li>\n<li><code>Initial state</code> (Startpseudozustand)</li>\n<li><code>TestFailed = FALSE</code> (Bit 0 nicht gesetzt)</li>\n<li><code>TestFailed = TRUE</code> (Bit 0 gesetzt)</li>\n<li><strong>Schnittstellen & Operationen:</strong></li>\n<li><code>Dem_SetEventStatus(EventId, EventStatus)</code> / <code>Dem_ReportErrorStatus(EventId, EventStatus)</code> mit den Statuswerten <code>DEM_EVENT_STATUS_PASSED</code> und <code>DEM_EVENT_STATUS_FAILED</code></li>\n<li><code>Dem_ResetEventStatus(EventId)</code> (gemäß <code>[SWS_Dem_00187]</code>)</li>\n<li><code>Dem_&lt;…&gt;ClearDTC(DTC, DTCFormat, DTCOrigin)</code> (gemäß <code>[SWS_Dem_00385]</code>)</li>\n<li><strong>Signal/Status:</strong></li>\n<li>Statusbit 0 (<code>Bit 0</code> bzw. <code>TestFailed</code>) des DTC-Status-Bytes.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung:</strong> Beim Eintritt über den Startzustand (<code>Initial state</code>) wird Bit 0 auf den Initialwert gesetzt; der Folgezustand ist <code>TestFailed = FALSE</code>.</li>\n<li><strong>Übergang nach TRUE:</strong> Aus dem Zustand <code>TestFailed = FALSE</code> führt das Ereignis <code>Dem_[SetEvent|ReportError]Status(EventId, EventStatus = DEM_EVENT_STATUS_FAILED)</code> [B] in den Zustand <code>TestFailed = TRUE</code>.</li>\n<li><strong>Selbstübergang TRUE:</strong> Tritt im Zustand <code>TestFailed = TRUE</code> erneut <code>Dem_[SetEvent|ReportError]Status(EventId, EventStatus = DEM_EVENT_STATUS_FAILED)</code> auf, verbleibt das Bit im Zustand <code>TestFailed = TRUE</code>.</li>\n<li><strong>Rückfall nach FALSE:</strong> Ein Zustandswechsel von <code>TestFailed = TRUE</code> nach <code>TestFailed = FALSE</code> erfolgt durch logisches ODER dreier Auslöser [A]:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Dem_[SetEvent|ReportError]Status(EventId, EventStatus = DEM_EVENT_STATUS_PASSED)</code></li>\n<li><code>Dem_ResetEventStatus(EventId)</code></li>\n<li><code>Dem_&lt;…&gt;ClearDTC(DTC, DTCFormat, DTCOrigin)</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Selbstübergang FALSE:</strong> Im Zustand <code>TestFailed = FALSE</code> belässt der Aufruf von <code>Dem_[SetEvent|ReportError]Status(EventId, EventStatus = DEM_EVENT_STATUS_PASSED)</code> das Bit unverändert auf <code>FALSE</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Das Verhalten ist für AUTOSAR Dem-Implementierungen normativ verbindlich für die Verwaltung des Bit 0 im UDS DTCStatusByte.</li>\n<li>Implementierer müssen beachten, dass nicht nur ein explizites Testergebnis (<code>DEM_EVENT_STATUS_PASSED</code>), sondern auch das Zurücksetzen (<code>Dem_ResetEventStatus</code>) oder das Löschen von DTCs (<code>Dem_&lt;…&gt;ClearDTC</code>) das Bit 0 auf 0 (<code>FALSE</code>) zurücksetzt.</li>\n<li>Diagnose-Fehlerberichte (<code>DEM_EVENT_STATUS_FAILED</code>) setzen das Bit unmittelbar auf 1 (<code>TRUE</code>), unabhängig davon, ob zuvor ein Pass vorlag.</li>\n</ul>"}], "trans": [{"from": "FIG-ffa2fbd3856cdca6", "to": "FIG-d40571ea7894622b", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
